from pathlib import Path
import re, sys, json
files=[Path('Home.md'),Path('docs/README.md'),Path('agents/README.md'),Path('remark/README.md'),Path('README.md')]
missing=[]
for f in files:
    text=f.read_text()
    # markdown links only local without anchors
    for m in re.finditer(r'\[[^\]]+\]\(([^)]+)\)', text):
        target=m.group(1)
        if '://' in target or target.startswith('#'):
            continue
        target=target.split('#',1)[0]
        if not target:
            continue
        p=(f.parent/target).resolve()
        if not p.exists():
            missing.append((str(f),target))
    for m in re.finditer(r'\[\[([^\]|#]+)(?:#[^\]|]+)?(?:\|[^\]]+)?\]\]', text):
        target=m.group(1)
        p=f.parent/target
        candidates=[p, p.with_suffix('.md'), Path(target), Path(target).with_suffix('.md')]
        if not any(c.exists() for c in candidates):
            missing.append((str(f),target))
if missing:
    print('missing links:')
    for item in missing:
        print(item)
    sys.exit(1)
print('checked', len(files), 'files; all local links resolve')
